import numpy as np
def solve(g):
    a=np.array(g); H,W=a.shape
    seen=np.zeros_like(a,bool); out=[row[:] for row in g]
    def comp(seed):
        stack=[seed]; s=set()
        while stack:
            r,c=stack.pop()
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and not seen[rr,cc] and a[rr,cc]!=0:
                    seen[rr,cc]=True; stack.append((rr,cc)); s.add((rr,cc))
        return s
    for r in range(H):
        for c in range(W):
            if a[r,c]!=0 and not seen[r,c]:
                seen[r,c]=True
                s=comp((r,c))
                rs=[p[0] for p in s]; cs=[p[1] for p in s]
                r0,c0=min(rs),min(cs); h=max(rs)-r0+1; w=max(cs)-c0+1
                # ring colors: diagonal sampling one per inset, dedup consecutive
                seq=[]
                for i in range((min(h,w)+1)//2):
                    col=g[r0+i][c0+i]
                    if not seq or seq[-1]!=col: seq.append(col)
                # thickness may be 2: skip duplicates handled; but check spacing
                m={old:new for old,new in zip(seq,seq[::-1])}
                for (rr,cc) in s:
                    out[rr][cc]=m[g[rr][cc]]
    return out
